    rdfs:comment "Inverse of hasItemNumberIdentification; relates a C212ItemNumberIdentification to its LIN_Segment." ;
    rdfs:domain :C212ItemNumberIdentification ;
    rdfs:range :LIN_Segment .

:hasChargeIdentification a owl:ObjectProperty ;
    rdfs:label "has charge identification composite" ;
    rdfs:comment "Relates an ALC_Segment to its C243ChargeIdentification composite." ;
    rdfs:domain :ALC_Segment ;
    rdfs:range :C243ChargeIdentification ;
    owl:inverseOf :isChargeIdentificationOf .

:isChargeIdentificationOf a owl:ObjectProperty ;
    rdfs:label "is charge identification of" ;
    rdfs:comment "Inverse of hasChargeIdentification; relates a C243ChargeIdentification to its ALC_Segment." ;
    rdfs:domain :C243ChargeIdentification ;
    rdfs:range :ALC_Segment .

:hasTaxRateDetails a owl:ObjectProperty ;
    rdfs:label "has tax rate details composite" ;
    rdfs:comment "Relates a TAX_Segment to its C509TaxRateDetails composite." ;
    rdfs:domain :TAX_Segment ;
    rdfs:range :C509TaxRateDetails ;
    owl:inverseOf :isTaxRateDetailsOf .

:isTaxRateDetailsOf a owl:ObjectProperty ;
    rdfs:label "is tax rate details of" ;
    rdfs:comment "Inverse of hasTaxRateDetails; relates a C509TaxRateDetails to its TAX_Segment." ;
    rdfs:domain :C509TaxRateDetails ;
    rdfs:range :TAX_Segment .

:hasCurrency a owl:ObjectProperty ;
    rdfs:label "has currency segment" ;
    rdfs:comment "Relates an InvoiceHeader to a CUX_Segment for currency specification." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :CUX_Segment ;
    owl:inverseOf :isCurrencyOf .

:isCurrencyOf a owl:ObjectProperty ;
    rdfs:label "is currency of" ;
    rdfs:comment "Inverse of hasCurrency; relates a CUX_Segment to its InvoiceHeader." ;
    rdfs:domain :CUX_Segment ;
    rdfs:range :InvoiceHeader .

:hasCurrencyComposite a owl:ObjectProperty ;
    rdfs:label "has currency composite" ;
    rdfs:comment "Relates a CUX_Segment to its C504CurrencyDetails composite." ;
    rdfs:domain :CUX_Segment ;
    rdfs:range :C504CurrencyDetails ;
    owl:inverseOf :isCurrencyCompositeOf .

:isCurrencyCompositeOf a owl:ObjectProperty ;
    rdfs:label "is currency composite of" ;
    rdfs:comment "Inverse of hasCurrencyComposite; relates a C504CurrencyDetails to its CUX_Segment." ;
    rdfs:domain :C504CurrencyDetails ;
    rdfs:range :CUX_Segment .

:hasTermsOfDelivery a owl:ObjectProperty ;
    rdfs:label "has terms of delivery segment" ;
    rdfs:comment "Relates an InvoiceHeader to a TOD_Segment for Incoterms and delivery conditions." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :TOD_Segment ;
    owl:inverseOf :isTermsOfDeliveryOf .

:isTermsOfDeliveryOf a owl:ObjectProperty ;
    rdfs:label "is terms of delivery of" ;
    rdfs:comment "Inverse of hasTermsOfDelivery; relates a TOD_Segment to its InvoiceHeader." ;
    rdfs:domain :TOD_Segment ;
    rdfs:range :InvoiceHeader .

#################################################################
# Data Properties
#################################################################
:hasQuantity a owl:DatatypeProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Relates a LineItem to its quantity as a decimal value." ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal .

:hasInvoiceAmount a owl:DatatypeProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "The total invoice amount in the summary section." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range xsd:decimal .

:hasInvoiceNumber a owl:DatatypeProperty ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number as a string." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:hasDocumentDate a owl:DatatypeProperty ;
    rdfs:label "has document date" ;
    rdfs:comment "The document date as a string (ISO 8601 format recommended)." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:hasReferenceNumber a owl:DatatypeProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "A reference number for the invoice, as a string." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:hasTaxTotal a owl:DatatypeProperty ;
    rdfs:label "has tax total" ;
    rdfs:comment "The total tax amount for the invoice." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range xsd:decimal .

#################################################################
# Advanced OWL Restrictions & Axioms
#################################################################

:LineItem a owl:Class ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf (
            :Item
            [ a owl:Restriction ; owl:onProperty :itemOf ; owl:someValuesFrom :Item ]
            [ a owl:Restriction ; owl:onProperty :hasNetPrice ; owl:someValuesFrom :Price ]
            [ a owl:Restriction ; owl:onProperty :hasQuantity ; owl:someValuesFrom xsd:decimal ]
        )
    ] .

:RoleAssignment a owl:Class ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf (
            [ a owl:Restriction ; owl:onProperty :hasRole ; owl:someValuesFrom :AgentRole ]
            [ a owl:Restriction ; owl:onProperty :forInvoice ; owl:someValuesFrom :InvoiceMessage ]
        )
    ] .

:InvoiceMessage a owl:Class ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf (
            :Message
            [ a owl:Restriction ; owl:onProperty :hasHeader ; owl:someValuesFrom :InvoiceHeader ]
            [ a owl:Restriction ; owl:onProperty :hasDetail ; owl:someValuesFrom :InvoiceDetail ]
            [ a owl:Restriction ; owl:onProperty :hasSummary ; owl:someValuesFrom :InvoiceSummary ]
        )
    ] .

:Organization a owl:Class ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf (
            [ a owl:Restriction ; owl:onProperty :hasIdentifier ; owl:someValuesFrom :Identifier ]
        )
    ] .

#################################################################
# Disjointness & DisjointUnion
#################################################################
:InvoiceHeader owl:disjointWith :InvoiceDetail, :InvoiceSummary .
:InvoiceDetail owl:disjointWith :InvoiceSummary .
:Organization owl:disjointWith :Item .
:Segment owl:disjointWith :CompositeDataElement .
:CompositeDataElement owl:disjointWith :SimpleDataElement .

:InvoiceHeader owl:disjointUnionOf ( :InvoiceHeader :InvoiceDetail :InvoiceSummary ) .

function.arguments:
{"key":"current_owl","value":"@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoic-d96a>
    a owl:Ontology ;
    rdfs:label "EDIFACT D96A INVOIC Ontology" ;
    rdfs:comment "A profoundly structured ontology for the UN/EDIFACT D96A INVOIC message, supporting deep segment, composite, and business role modeling, aligned with EANCOM and EN 16931-1." .

#################################################################
# Classes: Segments, Composites, Core
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The UN/EDIFACT interchange envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic UN/EDIFACT message container." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "INVOIC Message" ;
    rdfs:comment "A D96A INVOIC message for global trade invoices." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A generic EDIFACT segment, the basic structural unit of a message." .

:BGM_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message (BGM) segment identifying document type and number." .

:NAD_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment, identifying parties and their roles." .

:MOA_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "MOA Segment" ;
    rdfs:comment "Monetary Amount segment, used for invoice totals and line amounts." .

:DTM_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "DTM Segment" ;
    rdfs:comment "Date/Time/Period segment for document and transaction dates." .

:LIN_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "LIN Segment" ;
    rdfs:comment "Line Item segment, identifying invoice line and item codes." .

:PIA_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "PIA Segment" ;
    rdfs:comment "Additional Product ID segment for alternative item identification." .

:QTY_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "QTY Segment" ;
    rdfs:comment "Quantity segment specifying item or document quantities." .

:PRI_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "PRI Segment" ;
    rdfs:comment "Price segment for line item pricing details." .

:TAX_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "TAX Segment" ;
    rdfs:comment "Tax information segment for VAT and other taxes." .

:RFF_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "RFF Segment" ;
    rdfs:comment "Reference segment for additional document references." .

:ALC_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "ALC Segment" ;
    rdfs:comment "Allowance/Charge segment for discounts, surcharges, etc." .

:PAC_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "PAC Segment" ;
    rdfs:comment "Packaging segment for package details." .

:UNS_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "UNS Segment" ;
    rdfs:comment "Section control segment separating header, detail, and summary sections." .

:CUX_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "CUX Segment" ;
    rdfs:comment "Currency segment for specifying invoice currency." .

:TOD_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "TOD Segment" ;
    rdfs:comment "Terms of Delivery segment for Incoterms and delivery conditions." .

#################################################################
# Composite Data Elements (D96A/EANCOM)
#################################################################
:C516_MonetaryAmount a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C516 Monetary Amount" ;
    rdfs:comment "Composite for monetary amount details (qualifier, amount, currency)." .

:C507_DateTimePeriod a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C507 Date/Time/Period" ;
    rdfs:comment "Composite for date/time period details (qualifier, value, format)." .

:C002_DocumentMessageName a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C002 Document/Message Name" ;
    rdfs:comment "Composite for document/message type (code, code list, agency)." .

:C080PartyName a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C080 Party Name" ;
    rdfs:comment "Composite for organization or party names." .

:C082PartyIdentification a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C082 Party Identification" ;
    rdfs:comment "Composite for party identification codes (GLN, etc.)." .

:C186QuantityDetails a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C186 Quantity Details" ;
    rdfs:comment "Composite for quantity details (qualifier, value, unit)." .

:C212ItemNumberIdentification a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C212 Item Number Identification" ;
    rdfs:comment "Composite for item identification (GTIN, supplier code, etc.)." .

:C243ChargeIdentification a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C243 Charge Identification" ;
    rdfs:comment "Composite for charge identification details." .

:C509TaxRateDetails a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C509 Tax Rate Details" ;
    rdfs:comment "Composite for tax rate and category details." .

:C504CurrencyDetails a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C504 Currency Details" ;
    rdfs:comment "Composite for currency code and qualifier details." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "An EDIFACT composite data element." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple atomic data element in EDIFACT." .

#################################################################
# Document Structure: Header, Detail, Summary, Line
#################################################################
:InvoiceHeader a owl:Class ;
    rdfs:label "Invoice Header" ;
    rdfs:comment "Header section of an invoice message, containing general document data." .

:InvoiceDetail a owl:Class ;
    rdfs:label "Invoice Detail" ;
    rdfs:comment "Detail section of an invoice message, containing line items." .

:InvoiceSummary a owl:Class ;
    rdfs:label "Invoice Summary" ;
    rdfs:comment "Summary section of an invoice message, containing totals and tax information." .

:LineItem a owl:Class ;
    rdfs:subClassOf :Item ;
    rdfs:label "Invoice Line Item" ;
    rdfs:comment "A single line item in the invoice, referencing an item and its details." .

#################################################################
# Business Entities: Organizations, Roles, Addresses
#################################################################
:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A company, buyer, supplier, or other party involved in the invoice." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A specific role (e.g., Buyer, Supplier, Delivery Party) played by an organization in a transaction." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A pivot class for reifying the relation between an organization, its role, and the invoice context." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address associated with an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier (e.g., GLN, VAT number) for organizations or items." .

:GlobalLocationNumber a owl:Class ;
    rdfs:subClassOf :Identifier ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A GS1 Global Location Number for unique party identification." .

#################################################################
# Item, Price, Process, Validation
#################################################################
:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A tradable good or service referenced in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value associated with an item or line item." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process (e.g., Purchase-to-Pay) to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint for validating business rules (e.g., SHACL shapes)." .

#################################################################
# Object Properties (with inverses)
#################################################################
:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an InterchangeEnvelope to the contained Message." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "Inverse of containsMessage; relates a Message to its InterchangeEnvelope." ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a Message to its constituent Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:label "is segment of" ;
    rdfs:comment "Inverse of hasSegment; relates a Segment to its Message." ;
    rdfs:domain :Segment ;
    rdfs:range :Message .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:label "has composite element" ;
    rdfs:comment "Relates a Segment to its CompositeDataElements." ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:label "is composite element of" ;
    rdfs:comment "Inverse of hasCompositeElement; relates a CompositeDataElement to its Segment." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:label "has simple element" ;
    rdfs:comment "Relates a CompositeDataElement to its SimpleDataElements." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:label "is simple element of" ;
    rdfs:comment "Inverse of hasSimpleElement; relates a SimpleDataElement to its CompositeDataElement." ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement .

:hasHeader a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has header" ;
    rdfs:comment "Relates an InvoiceMessage to its header section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceHeader ;
    owl:inverseOf :isHeaderOf .

:isHeaderOf a owl:ObjectProperty ;
    rdfs:label "is header of" ;
    rdfs:comment "Inverse of hasHeader; relates an InvoiceHeader to its InvoiceMessage." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :InvoiceMessage .

:hasDetail a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has detail" ;
    rdfs:comment "Relates an InvoiceMessage to its detail section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceDetail ;
    owl:inverseOf :isDetailOf .

:isDetailOf a owl:ObjectProperty ;
    rdfs:label "is detail of" ;
    rdfs:comment "Inverse of hasDetail; relates an InvoiceDetail to its InvoiceMessage." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :InvoiceMessage .

:hasSummary a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has summary" ;
    rdfs:comment "Relates an InvoiceMessage to its summary section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceSummary ;
    owl:inverseOf :isSummaryOf .

:isSummaryOf a owl:ObjectProperty ;
    rdfs:label "is summary of" ;
    rdfs:comment "Inverse of hasSummary; relates an InvoiceSummary to its InvoiceMessage." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :InvoiceMessage .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "Relates an InvoiceMessage to an Organization involved in the transaction." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    owl:inverseOf :isOrganizationInvolvedIn .

:isOrganizationInvolvedIn a owl:ObjectProperty ;
    rdfs:label "is organization involved in" ;
    rdfs:comment "Inverse of involvesOrganization; relates an Organization to its InvoiceMessage." ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage .

:playsRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "plays role assignment" ;
    rdfs:comment "Relates an Organization to a RoleAssignment (pivot class)." ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    owl:inverseOf :isRoleAssignmentOf .

:isRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:label "is role assignment of" ;
    rdfs:comment "Inverse of playsRole; relates a RoleAssignment to its Organization." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization .

:forInvoice a owl:ObjectProperty ;
    rdfs:label "for invoice" ;
    rdfs:comment "Relates a RoleAssignment to the InvoiceMessage context." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasRoleAssignment .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Inverse of forInvoice; relates an InvoiceMessage to its RoleAssignments." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :RoleAssignment .

:hasRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has role" ;
    rdfs:comment "Relates a RoleAssignment to the AgentRole played." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    owl:inverseOf :isRoleOfAssignment .

:isRoleOfAssignment a owl:ObjectProperty ;
    rdfs:label "is role of assignment" ;
    rdfs:comment "Inverse of hasRole; relates an AgentRole to its RoleAssignment." ;
    rdfs:domain :AgentRole ;
    rdfs:range :RoleAssignment .

:hasAddress a owl:ObjectProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Relates an Organization to an Address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
    rdfs:label "is address of" ;
    rdfs:comment "Inverse of hasAddress; relates an Address to its Organization." ;
    rdfs:domain :Address ;
    rdfs:range :Organization .

:hasIdentifier a owl:ObjectProperty , owl:InverseFunctionalProperty ;
    rdfs:label "has identifier" ;
    rdfs:comment "Relates an Organization to an Identifier (GLN, VAT, etc.)." ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    owl:inverseOf :isIdentifierOf .

:isIdentifierOf a owl:ObjectProperty ;
    rdfs:label "is identifier of" ;
    rdfs:comment "Inverse of hasIdentifier; relates an Identifier to its Organization." ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization .

:hasLineItem a owl:ObjectProperty ;
    rdfs:label "has line item" ;
    rdfs:comment "Relates an InvoiceDetail section to its LineItems." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :LineItem ;
    owl:inverseOf :isLineItemOf .

:isLineItemOf a owl:ObjectProperty ;
    rdfs:label "is line item of" ;
    rdfs:comment "Inverse of hasLineItem; relates a LineItem to its InvoiceDetail." ;
    rdfs:domain :LineItem ;
    rdfs:range :InvoiceDetail .

:itemOf a owl:ObjectProperty ;
    rdfs:label "item of" ;
    rdfs:comment "Relates a LineItem to the Item being referenced." ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    owl:inverseOf :hasLineItemRef .

:hasLineItemRef a owl:ObjectProperty ;
    rdfs:label "has line item reference" ;
    rdfs:comment "Inverse of itemOf; relates an Item to its LineItems." ;
    rdfs:domain :Item ;
    rdfs:range :LineItem .

:hasNetPrice a owl:ObjectProperty ;
    rdfs:label "has net price" ;
    rdfs:comment "Relates a LineItem to its Price." ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    owl:inverseOf :isNetPriceOf .

:isNetPriceOf a owl:ObjectProperty ;
    rdfs:label "is net price of" ;
    rdfs:comment "Inverse of hasNetPrice; relates a Price to its LineItem." ;
    rdfs:domain :Price ;
    rdfs:range :LineItem .

:assignedToProcess a owl:ObjectProperty ;
    rdfs:label "assigned to process" ;
    rdfs:comment "Relates an InvoiceMessage to a BusinessProcess context." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    owl:inverseOf :isProcessAssignmentOf .

:isProcessAssignmentOf a owl:ObjectProperty ;
    rdfs:label "is process assignment of" ;
    rdfs:comment "Inverse of assignedToProcess; relates a BusinessProcess to its InvoiceMessage." ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage .

:hasValidationConstraint a owl:ObjectProperty ;
    rdfs:label "has validation constraint" ;
    rdfs:comment "Relates an InvoiceMessage to a ValidationConstraint (e.g., SHACL shape)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint ;
    owl:inverseOf :isValidationConstraintOf .

:isValidationConstraintOf a owl:ObjectProperty ;
    rdfs:label "is validation constraint of" ;
    rdfs:comment "Inverse of hasValidationConstraint; relates a ValidationConstraint to its InvoiceMessage." ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage .

:hasMonetaryAmount a owl:ObjectProperty ;
    rdfs:label "has monetary amount segment" ;
    rdfs:comment "Relates an InvoiceHeader to a MOA_Segment for monetary values." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :MOA_Segment ;
    owl:inverseOf :isMonetaryAmountOf .

:isMonetaryAmountOf a owl:ObjectProperty ;
    rdfs:label "is monetary amount of" ;
    rdfs:comment "Inverse of hasMonetaryAmount; relates a MOA_Segment to its InvoiceHeader." ;
    rdfs:domain :MOA_Segment ;
    rdfs:range :InvoiceHeader .

:hasDateTime a owl:ObjectProperty ;
    rdfs:label "has date/time segment" ;
    rdfs:comment "Relates an InvoiceHeader to a DTM_Segment for document dates." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :DTM_Segment ;
    owl:inverseOf :isDateTimeOf .

:isDateTimeOf a owl:ObjectProperty ;
    rdfs:label "is date/time of" ;
    rdfs:comment "Inverse of hasDateTime; relates a DTM_Segment to its InvoiceHeader." ;
    rdfs:domain :DTM_Segment ;
    rdfs:range :InvoiceHeader .

:hasLineMonetaryAmount a owl:ObjectProperty ;
    rdfs:label "has line monetary amount segment" ;
    rdfs:comment "Relates a LineItem to a MOA_Segment for line-level amounts." ;
    rdfs:domain :LineItem ;
    rdfs:range :MOA_Segment ;
    owl:inverseOf :isLineMonetaryAmountOf .

:isLineMonetaryAmountOf a owl:ObjectProperty ;
    rdfs:label "is line monetary amount of" ;
    rdfs:comment "Inverse of hasLineMonetaryAmount; relates a MOA_Segment to its LineItem." ;
    rdfs:domain :MOA_Segment ;
    rdfs:range :LineItem .

:hasLineDateTime a owl:ObjectProperty ;
    rdfs:label "has line date/time segment" ;
    rdfs:comment "Relates a LineItem to a DTM_Segment for line-level dates." ;
    rdfs:domain :LineItem ;
    rdfs:range :DTM_Segment ;
    owl:inverseOf :isLineDateTimeOf .

:isLineDateTimeOf a owl:ObjectProperty ;
    rdfs:label "is line date/time of" ;
    rdfs:comment "Inverse of hasLineDateTime; relates a DTM_Segment to its LineItem." ;
    rdfs:domain :DTM_Segment ;
    rdfs:range :LineItem .

:hasLineSegment a owl:ObjectProperty ;
    rdfs:label "has line segment" ;
    rdfs:comment "Relates an InvoiceDetail to its LIN_Segment." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :LIN_Segment ;
    owl:inverseOf :isLineSegmentOf .

:isLineSegmentOf a owl:ObjectProperty ;
    rdfs:label "is line segment of" ;
    rdfs:comment "Inverse of hasLineSegment; relates a LIN_Segment to its InvoiceDetail." ;
    rdfs:domain :LIN_Segment ;
    rdfs:range :InvoiceDetail .

:hasItemAdditionalIdentification a owl:ObjectProperty ;
    rdfs:label "has item additional identification" ;
    rdfs:comment "Relates a LineItem to a PIA_Segment for alternative item codes." ;
    rdfs:domain :LineItem ;
    rdfs:range :PIA_Segment ;
    owl:inverseOf :isItemAdditionalIdentificationOf .

:isItemAdditionalIdentificationOf a owl:ObjectProperty ;
    rdfs:label "is item additional identification of" ;
    rdfs:comment "Inverse of hasItemAdditionalIdentification; relates a PIA_Segment to its LineItem." ;
    rdfs:domain :PIA_Segment ;
    rdfs:range :LineItem .

:hasLineQuantity a owl:ObjectProperty ;
    rdfs:label "has line quantity segment" ;
    rdfs:comment "Relates a LineItem to a QTY_Segment for line-level quantities." ;
    rdfs:domain :LineItem ;
    rdfs:range :QTY_Segment ;
    owl:inverseOf :isLineQuantityOf .

:isLineQuantityOf a owl:ObjectProperty ;
    rdfs:label "is line quantity of" ;
    rdfs:comment "Inverse of hasLineQuantity; relates a QTY_Segment to its LineItem." ;
    rdfs:domain :QTY_Segment ;
    rdfs:range :LineItem .

:hasLinePrice a owl:ObjectProperty ;
    rdfs:label "has line price segment" ;
    rdfs:comment "Relates a LineItem to a PRI_Segment for line-level price details." ;
    rdfs:domain :LineItem ;
    rdfs:range :PRI_Segment ;
    owl:inverseOf :isLinePriceOf .

:isLinePriceOf a owl:ObjectProperty ;
    rdfs:label "is line price of" ;
    rdfs:comment "Inverse of hasLinePrice; relates a PRI_Segment to its LineItem." ;
    rdfs:domain :PRI_Segment ;
    rdfs:range :LineItem .

:hasTaxSegment a owl:ObjectProperty ;
    rdfs:label "has tax segment" ;
    rdfs:comment "Relates an InvoiceSummary to a TAX_Segment for tax details." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :TAX_Segment ;
    owl:inverseOf :isTaxSegmentOf .

:isTaxSegmentOf a owl:ObjectProperty ;
    rdfs:label "is tax segment of" ;
    rdfs:comment "Inverse of hasTaxSegment; relates a TAX_Segment to its InvoiceSummary." ;
    rdfs:domain :TAX_Segment ;
    rdfs:range :InvoiceSummary .

:hasReference a owl:ObjectProperty ;
    rdfs:label "has reference segment" ;
    rdfs:comment "Relates an InvoiceHeader to a RFF_Segment for references." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :RFF_Segment ;
    owl:inverseOf :isReferenceOf .

:isReferenceOf a owl:ObjectProperty ;
    rdfs:label "is reference of" ;
    rdfs:comment "Inverse of hasReference; relates a RFF_Segment to its InvoiceHeader." ;
    rdfs:domain :RFF_Segment ;
    rdfs:range :InvoiceHeader .

:hasAllowanceCharge a owl:ObjectProperty ;
    rdfs:label "has allowance/charge segment" ;
    rdfs:comment "Relates an InvoiceSummary to an ALC_Segment for allowances and charges." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :ALC_Segment ;
    owl:inverseOf :isAllowanceChargeOf .

:isAllowanceChargeOf a owl:ObjectProperty ;
    rdfs:label "is allowance/charge of" ;
    rdfs:comment "Inverse of hasAllowanceCharge; relates an ALC_Segment to its InvoiceSummary." ;
    rdfs:domain :ALC_Segment ;
    rdfs:range :InvoiceSummary .

:hasPackaging a owl:ObjectProperty ;
    rdfs:label "has packaging segment" ;
    rdfs:comment "Relates an InvoiceDetail to a PAC_Segment for packaging details." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :PAC_Segment ;
    owl:inverseOf :isPackagingOf .

:isPackagingOf a owl:ObjectProperty ;
    rdfs:label "is packaging of" ;
    rdfs:comment "Inverse of hasPackaging; relates a PAC_Segment to its InvoiceDetail." ;
    rdfs:domain :PAC_Segment ;
    rdfs:range :InvoiceDetail .

:hasSectionControl a owl:ObjectProperty ;
    rdfs:label "has section control segment" ;
    rdfs:comment "Relates an InvoiceMessage to a UNS_Segment for section separation." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :UNS_Segment ;
    owl:inverseOf :isSectionControlOf .

:isSectionControlOf a owl:ObjectProperty ;
    rdfs:label "is section control of" ;
    rdfs:comment "Inverse of hasSectionControl; relates a UNS_Segment to its InvoiceMessage." ;
    rdfs:domain :UNS_Segment ;
    rdfs:range :InvoiceMessage .

:hasMonetaryComposite a owl:ObjectProperty ;
    rdfs:label "has monetary composite" ;
    rdfs:comment "Relates a MOA_Segment to its C516_MonetaryAmount composite." ;
    rdfs:domain :MOA_Segment ;
    rdfs:range :C516_MonetaryAmount ;
    owl:inverseOf :isMonetaryCompositeOf .

:isMonetaryCompositeOf a owl:ObjectProperty ;
    rdfs:label "is monetary composite of" ;
    rdfs:comment "Inverse of hasMonetaryComposite; relates a C516_MonetaryAmount to its MOA_Segment." ;
    rdfs:domain :C516_MonetaryAmount ;
    rdfs:range :MOA_Segment .

:hasDateTimeComposite a owl:ObjectProperty ;
    rdfs:label "has date/time composite" ;
    rdfs:comment "Relates a DTM_Segment to its C507_DateTimePeriod composite." ;
    rdfs:domain :DTM_Segment ;
    rdfs:range :C507_DateTimePeriod ;
    owl:inverseOf :isDateTimeCompositeOf .

:isDateTimeCompositeOf a owl:ObjectProperty ;
    rdfs:label "is date/time composite of" ;
    rdfs:comment "Inverse of hasDateTimeComposite; relates a C507_DateTimePeriod to its DTM_Segment." ;
    rdfs:domain :C507_DateTimePeriod ;
    rdfs:range :DTM_Segment .

:hasDocumentMessageName a owl:ObjectProperty ;
    rdfs:label "has document message name composite" ;
    rdfs:comment "Relates a BGM_Segment to its C002_DocumentMessageName composite." ;
    rdfs:domain :BGM_Segment ;
    rdfs:range :C002_DocumentMessageName ;
    owl:inverseOf :isDocumentMessageNameOf .

:isDocumentMessageNameOf a owl:ObjectProperty ;
    rdfs:label "is document message name of" ;
    rdfs:comment "Inverse of hasDocumentMessageName; relates a C002_DocumentMessageName to its BGM_Segment." ;
    rdfs:domain :C002_DocumentMessageName ;
    rdfs:range :BGM_Segment .

:hasPartyName a owl:ObjectProperty ;
    rdfs:label "has party name composite" ;
    rdfs:comment "Relates a NAD_Segment to its C080PartyName composite." ;
    rdfs:domain :NAD_Segment ;
    rdfs:range :C080PartyName ;
    owl:inverseOf :isPartyNameOf .

:isPartyNameOf a owl:ObjectProperty ;
    rdfs:label "is party name of" ;
    rdfs:comment "Inverse of hasPartyName; relates a C080PartyName to its NAD_Segment." ;
    rdfs:domain :C080PartyName ;
    rdfs:range :NAD_Segment .

:hasPartyIdentification a owl:ObjectProperty ;
    rdfs:label "has party identification composite" ;
    rdfs:comment "Relates a NAD_Segment to its C082PartyIdentification composite." ;
    rdfs:domain :NAD_Segment ;
    rdfs:range :C082PartyIdentification ;
    owl:inverseOf :isPartyIdentificationOf .

:isPartyIdentificationOf a owl:ObjectProperty ;
    rdfs:label "is party identification of" ;
    rdfs:comment "Inverse of hasPartyIdentification; relates a C082PartyIdentification to its NAD_Segment." ;
    rdfs:domain :C082PartyIdentification ;
    rdfs:range :NAD_Segment .

:hasQuantityDetails a owl:ObjectProperty ;
    rdfs:label "has quantity details composite" ;
    rdfs:comment "Relates a QTY_Segment to its C186QuantityDetails composite." ;
    rdfs:domain :QTY_Segment ;
    rdfs:range :C186QuantityDetails ;
    owl:inverseOf :isQuantityDetailsOf .

:isQuantityDetailsOf a owl:ObjectProperty ;
    rdfs:label "is quantity details of" ;
    rdfs:comment "Inverse of hasQuantityDetails; relates a C186QuantityDetails to its QTY_Segment." ;
    rdfs:domain :C186QuantityDetails ;
    rdfs:range :QTY_Segment .

:hasItemNumberIdentification a owl:ObjectProperty ;
    rdfs:label "has item number identification composite" ;
    rdfs:comment "Relates a LIN_Segment to its C212ItemNumberIdentification composite." ;
    rdfs:domain :LIN_Segment ;
    rdfs:range :C212ItemNumberIdentification ;
    owl:inverseOf :isItemNumberIdentificationOf .

:isItemNumberIdentificationOf a owl:ObjectProperty ;
    rdfs:label "is item number identification of" ;
    rdfs:comment "Inverse of hasItemNumberIdentification; relates a C212ItemNumberIdentification to its LIN_Segment." ;
    rdfs:domain :C212ItemNumberIdentification ;
    rdfs:range :LIN_Segment .

:hasChargeIdentification a owl:ObjectProperty ;
    rdfs:label "has charge identification composite" ;
    rdfs:comment "Relates an ALC_Segment to its C243ChargeIdentification composite." ;
    rdfs:domain :ALC_Segment ;
    rdfs:range :C243ChargeIdentification ;
    owl:inverseOf :isChargeIdentificationOf .

:isChargeIdentificationOf a owl:ObjectProperty ;
    rdfs:label "is charge identification of" ;
    rdfs:comment "Inverse of hasChargeIdentification; relates a C243ChargeIdentification to its ALC_Segment." ;
    rdfs:domain :C243ChargeIdentification ;
    rdfs:range :ALC_Segment .

:hasTaxRateDetails a owl:ObjectProperty ;
    rdfs:label "has tax rate details composite" ;
    rdfs:comment "Relates a TAX_Segment to its C509TaxRateDetails composite." ;
    rdfs:domain :TAX_Segment ;
    rdfs:range :C509TaxRateDetails ;
    owl:inverseOf :isTaxRateDetailsOf .

:isTaxRateDetailsOf a owl:ObjectProperty ;
    rdfs:label "is tax rate details of" ;
    rdfs:comment "Inverse of hasTaxRateDetails; relates a C509TaxRateDetails to its TAX_Segment." ;
    rdfs:domain :C509TaxRateDetails ;
    rdfs:range :TAX_Segment .

:hasCurrency a owl:ObjectProperty ;
    rdfs:label "has currency segment" ;
    rdfs:comment "Relates an InvoiceHeader to a CUX_Segment for currency specification." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :CUX_Segment ;
    owl:inverseOf :isCurrencyOf .

:isCurrencyOf a owl:ObjectProperty ;
    rdfs:label "is currency of" ;
    rdfs:comment "Inverse of hasCurrency; relates a CUX_Segment to its InvoiceHeader." ;
    rdfs:domain :CUX_Segment ;
    rdfs:range :InvoiceHeader .

:hasCurrencyComposite a owl:ObjectProperty ;
    rdfs:label "has currency composite" ;
    rdfs:comment "Relates a CUX_Segment to its C504CurrencyDetails composite." ;
    rdfs:domain :CUX_Segment ;
    rdfs:range :C504CurrencyDetails ;
    owl:inverseOf :isCurrencyCompositeOf .

:isCurrencyCompositeOf a owl:ObjectProperty ;
    rdfs:label "is currency composite of" ;
    rdfs:comment "Inverse of hasCurrencyComposite; relates a C504CurrencyDetails to its CUX_Segment." ;
    rdfs:domain :C504CurrencyDetails ;
    rdfs:range :CUX_Segment .

:hasTermsOfDelivery a owl:ObjectProperty ;
    rdfs:label "has terms of delivery segment" ;
    rdfs:comment "Relates an InvoiceHeader to a TOD_Segment for Incoterms and delivery conditions." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :TOD_Segment ;
    owl:inverseOf :isTermsOfDeliveryOf .

:isTermsOfDeliveryOf a owl:ObjectProperty ;
    rdfs:label "is terms of delivery of" ;
    rdfs:comment "Inverse of hasTermsOfDelivery; relates a TOD_Segment to its InvoiceHeader." ;
    rdfs:domain :TOD_Segment ;
    rdfs:range :InvoiceHeader .

#################################################################
# Data Properties
#################################################################
:hasQuantity a owl:DatatypeProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Relates a LineItem to its quantity as a decimal value." ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal .

:hasInvoiceAmount a owl:DatatypeProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "The total invoice amount in the summary section." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range xsd:decimal .

:hasInvoiceNumber a owl:DatatypeProperty ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number as a string." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:hasDocumentDate a owl:DatatypeProperty ;
    rdfs:label "has document date" ;
    rdfs:comment "The document date as a string (ISO 8601 format recommended)." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:hasReferenceNumber a owl:DatatypeProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "A reference number for the invoice, as a string." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:hasTaxTotal a owl:DatatypeProperty ;
    rdfs:label "has tax total" ;
    rdfs:comment "The total tax amount for the invoice." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range xsd:decimal .

#################################################################
# Advanced OWL Restrictions & Axioms
#################################################################

:LineItem a owl:Class ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf (
            :Item
            [ a owl:Restriction ; owl:onProperty :itemOf ; owl:someValuesFrom :Item ]
            [ a owl:Restriction ; owl:onProperty :hasNetPrice ; owl:someValuesFrom :Price ]
            [ a owl:Restriction ; owl:onProperty :hasQuantity ; owl:someValuesFrom xsd:decimal ]
        )
    ] .

:RoleAssignment a owl:Class ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf (
            [ a owl:Restriction ; owl:onProperty :hasRole ; owl:someValuesFrom :AgentRole ]
            [ a owl:Restriction ; owl:onProperty :forInvoice ; owl:someValuesFrom :InvoiceMessage ]
        )
    ] .

:InvoiceMessage a owl:Class ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf (
            :Message
            [ a owl:Restriction ; owl:onProperty :hasHeader ; owl:someValuesFrom :InvoiceHeader ]
            [ a owl:Restriction ; owl:onProperty :hasDetail ; owl:someValuesFrom :InvoiceDetail ]
            [ a owl:Restriction ; owl:onProperty :hasSummary ; owl:someValuesFrom :InvoiceSummary ]
        )
    ] .

:Organization a owl:Class ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf (
            [ a owl:Restriction ; owl:onProperty :hasIdentifier ; owl:someValuesFrom :Identifier ]
        )
    ] .

#################################################################
# Disjointness & DisjointUnion
#################################################################
:InvoiceHeader owl:disjointWith :InvoiceDetail, :InvoiceSummary .
:InvoiceDetail owl:disjointWith :InvoiceSummary .
:Organization owl:disjointWith :Item .
:Segment owl:disjointWith :CompositeDataElement .
:CompositeDataElement owl:disjointWith :SimpleDataElement .

:InvoiceHeader owl:disjointUnionOf ( :InvoiceHeader :InvoiceDetail :InvoiceSummary ) .
"}

args.owl_content:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoic-d96a>
    a owl:Ontology ;
    rdfs:label "EDIFACT D96A INVOIC Ontology" ;
    rdfs:comment "A profoundly structured ontology for the UN/EDIFACT D96A INVOIC message, supporting deep segment, composite, and business role modeling, aligned with EANCOM and EN 16931-1." .

#################################################################
# Classes: Segments, Composites, Core
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The UN/EDIFACT interchange envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic UN/EDIFACT message container." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "INVOIC Message" ;
    rdfs:comment "A D96A INVOIC message for global trade invoices." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A generic EDIFACT segment, the basic structural unit of a message." .

:BGM_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message (BGM) segment identifying document type and number." .

:NAD_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment, identifying parties and their roles." .

:MOA_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "MOA Segment" ;
    rdfs:comment "Monetary Amount segment, used for invoice totals and line amounts." .

:DTM_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "DTM Segment" ;
    rdfs:comment "Date/Time/Period segment for document and transaction dates." .

:LIN_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "LIN Segment" ;
    rdfs:comment "Line Item segment, identifying invoice line and item codes." .

:PIA_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "PIA Segment" ;
    rdfs:comment "Additional Product ID segment for alternative item identification." .

:QTY_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "QTY Segment" ;
    rdfs:comment "Quantity segment specifying item or document quantities." .

:PRI_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "PRI Segment" ;
    rdfs:comment "Price segment for line item pricing details." .

:TAX_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "TAX Segment" ;
    rdfs:comment "Tax information segment for VAT and other taxes." .

:RFF_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "RFF Segment" ;
    rdfs:comment "Reference segment for additional document references." .

:ALC_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "ALC Segment" ;
    rdfs:comment "Allowance/Charge segment for discounts, surcharges, etc." .

:PAC_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "PAC Segment" ;
    rdfs:comment "Packaging segment for package details." .

:UNS_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "UNS Segment" ;
    rdfs:comment "Section control segment separating header, detail, and summary sections." .

:CUX_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "CUX Segment" ;
    rdfs:comment "Currency segment for specifying invoice currency." .

:TOD_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "TOD Segment" ;
    rdfs:comment "Terms of Delivery segment for Incoterms and delivery conditions." .

#################################################################
# Composite Data Elements (D96A/EANCOM)
#################################################################
:C516_MonetaryAmount a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C516 Monetary Amount" ;
    rdfs:comment "Composite for monetary amount details (qualifier, amount, currency)." .

:C507_DateTimePeriod a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C507 Date/Time/Period" ;
    rdfs:comment "Composite for date/time period details (qualifier, value, format)." .

:C002_DocumentMessageName a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C002 Document/Message Name" ;
    rdfs:comment "Composite for document/message type (code, code list, agency)." .

:C080PartyName a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C080 Party Name" ;
    rdfs:comment "Composite for organization or party names." .

:C082PartyIdentification a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C082 Party Identification" ;
    rdfs:comment "Composite for party identification codes (GLN, etc.)." .

:C186QuantityDetails a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C186 Quantity Details" ;
    rdfs:comment "Composite for quantity details (qualifier, value, unit)." .

:C212ItemNumberIdentification a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C212 Item Number Identification" ;
    rdfs:comment "Composite for item identification (GTIN, supplier code, etc.)." .

:C243ChargeIdentification a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C243 Charge Identification" ;
    rdfs:comment "Composite for charge identification details." .

:C509TaxRateDetails a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C509 Tax Rate Details" ;
    rdfs:comment "Composite for tax rate and category details." .

:C504CurrencyDetails a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "C504 Currency Details" ;
    rdfs:comment "Composite for currency code and qualifier details." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "An EDIFACT composite data element." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple atomic data element in EDIFACT." .

#################################################################
# Document Structure: Header, Detail, Summary, Line
#################################################################
:InvoiceHeader a owl:Class ;
    rdfs:label "Invoice Header" ;
    rdfs:comment "Header section of an invoice message, containing general document data." .

:InvoiceDetail a owl:Class ;
    rdfs:label "Invoice Detail" ;
    rdfs:comment "Detail section of an invoice message, containing line items." .

:InvoiceSummary a owl:Class ;
    rdfs:label "Invoice Summary" ;
    rdfs:comment "Summary section of an invoice message, containing totals and tax information." .

:LineItem a owl:Class ;
    rdfs:subClassOf :Item ;
    rdfs:label "Invoice Line Item" ;
    rdfs:comment "A single line item in the invoice, referencing an item and its details." .

#################################################################
# Business Entities: Organizations, Roles, Addresses
#################################################################
:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A company, buyer, supplier, or other party involved in the invoice." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A specific role (e.g., Buyer, Supplier, Delivery Party) played by an organization in a transaction." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A pivot class for reifying the relation between an organization, its role, and the invoice context." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address associated with an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier (e.g., GLN, VAT number) for organizations or items." .

:GlobalLocationNumber a owl:Class ;
    rdfs:subClassOf :Identifier ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A GS1 Global Location Number for unique party identification." .

#################################################################
# Item, Price, Process, Validation
#################################################################
:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A tradable good or service referenced in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value associated with an item or line item." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process (e.g., Purchase-to-Pay) to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint for validating business rules (e.g., SHACL shapes)." .

#################################################################
# Object Properties (with inverses)
#################################################################
:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an InterchangeEnvelope to the contained Message." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "Inverse of containsMessage; relates a Message to its InterchangeEnvelope." ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope .

