@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoic-ontology> a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Ontology" ;
    rdfs:comment "A deep and profoundly structured OWL ontology for UN/EDIFACT INVOIC messages, covering D96A, EANCOM, EN16931-1, and P2P-O alignment." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The outermost envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A general EDIFACT message contained within an Interchange Envelope." .

:INVOICMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "INVOIC Message" ;
    rdfs:comment "An invoice message (INVOIC) in the EDIFACT standard." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment in an EDIFACT message, such as BGM or NAD." .

:BGMSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." .

:NADSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite data element." .

:Section a owl:Class ;
    rdfs:label "Section" ;
    rdfs:comment "A section of the message, either header, detail, or summary." .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :Section ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an INVOIC message, containing dates and references." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :Section ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section of an INVOIC message, listing line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :Section ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section of an INVOIC message, providing totals and taxes." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice, such as buyer or supplier." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in a business process (e.g., Buyer, Supplier)." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address associated with an organization." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A unique identifier for an organization location, such as a GLN." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "An itemized line in the invoice detailing a product or service." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in a line item." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price associated with a line item." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax element in the summary section of the invoice." .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "The total amount of the invoice." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number for the invoice document." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which an invoice can be assigned." .

:EN16931Compliance a owl:Class ;
    rdfs:label "EN 16931 Compliance" ;
    rdfs:comment "Compliance with the European Standard EN 16931-1." .

:P2POntologyAlignment a owl:Class ;
    rdfs:label "Purchase-to-Pay Ontology Alignment" ;
    rdfs:comment "Alignment with the Purchase-to-Pay Ontology (P2P-O)." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint for automated validation of invoice data." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A pivot class reifying the assignment of an AgentRole to an Organization in a specific INVOIC message context." .

#################################################################
# Disjoint Unions and Disjoint Classes
#################################################################

:Section owl:disjointUnionOf ( :HeaderSection :DetailSection :SummarySection ) .

:Organization owl:disjointWith :Address, :LineItem, :Section .
:Segment owl:disjointWith :Section .
:CompositeDataElement owl:disjointWith :SimpleDataElement .

#################################################################
# Object Properties and Inverses
#################################################################

:containsMessage a owl:ObjectProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an Interchange Envelope to contained Messages." .
:containsMessage rdf:type owl:FunctionalProperty .
:isContainedIn a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "is contained in Interchange Envelope" ;
    rdfs:comment "Indicates in which InterchangeEnvelope a Message is contained (inverse of containsMessage)." ;
    owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a Message to its Segments." .
:isSegmentOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "is segment of Message" ;
    rdfs:comment "Indicates the Message of which this Segment is a part (inverse of hasSegment)." ;
    owl:inverseOf :hasSegment .

:hasSection a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Section ;
    rdfs:label "has section" ;
    rdfs:comment "Links a Message to its Sections (header, detail, summary)." .
:isSectionOf a owl:ObjectProperty ;
    rdfs:domain :Section ;
    rdfs:range :Message ;
    rdfs:label "is section of Message" ;
    rdfs:comment "Indicates the Message to which this Section belongs (inverse of hasSection)." ;
    owl:inverseOf :hasSection .

:hasHeader a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :HeaderSection ;
    rdfs:label "has header" ;
    rdfs:comment "Links a Message to its Header Section." .
:hasHeader rdf:type owl:FunctionalProperty .
:isHeaderOf a owl:ObjectProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :Message ;
    rdfs:label "is header of Message" ;
    rdfs:comment "Indicates the Message for which this is the Header Section (inverse of hasHeader)." ;
    owl:inverseOf :hasHeader .

:hasDetail a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :DetailSection ;
    rdfs:label "has detail" ;
    rdfs:comment "Links a Message to its Detail Section." .
:hasDetail rdf:type owl:FunctionalProperty .
:isDetailOf a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :Message ;
    rdfs:label "is detail of Message" ;
    rdfs:comment "Indicates the Message for which this is the Detail Section (inverse of hasDetail)." ;
    owl:inverseOf :hasDetail .

:hasSummary a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :SummarySection ;
    rdfs:label "has summary" ;
    rdfs:comment "Links a Message to its Summary Section." .
:hasSummary rdf:type owl:FunctionalProperty .
:isSummaryOf a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Message ;
    rdfs:label "is summary of Message" ;
    rdfs:comment "Indicates the Message for which this is the Summary Section (inverse of hasSummary)." ;
    owl:inverseOf :hasSummary .

:hasLineItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "has line item" ;
    rdfs:comment "Links a Detail Section to its Line Items." .
:isLineItemOf a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    rdfs:label "is line item of Detail Section" ;
    rdfs:comment "Indicates the Detail Section to which this Line Item belongs (inverse of hasLineItem)." ;
    owl:inverseOf :hasLineItem .

:describesItem a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "describes item" ;
    rdfs:comment "Links a Line Item to the Item it describes." .
:describesItem rdf:type owl:FunctionalProperty .
:isDescribedByLineItem a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    rdfs:label "is described by Line Item" ;
    rdfs:comment "Indicates the Line Item that describes this Item (inverse of describesItem)." ;
    owl:inverseOf :describesItem .

:hasPrice a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    rdfs:label "has price" ;
    rdfs:comment "Links a Line Item to its Price." .
:hasPrice rdf:type owl:FunctionalProperty .
:isPriceOf a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    rdfs:label "is price of Line Item" ;
    rdfs:comment "Indicates the Line Item for which this is the Price (inverse of hasPrice)." ;
    owl:inverseOf :hasPrice .

:hasOrganization a owl:ObjectProperty ;
    rdfs:domain :NADSegment ;
    rdfs:range :Organization ;
    rdfs:label "has organization" ;
    rdfs:comment "Links a NAD Segment to an Organization participant." .
:isOrganizationOf a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :NADSegment ;
    rdfs:label "is organization of NAD Segment" ;
    rdfs:comment "Indicates the NAD Segment to which this Organization belongs (inverse of hasOrganization)." ;
    owl:inverseOf :hasOrganization .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Links an Organization to its RoleAssignment(s) in the invoice context." .
:isRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "is role assignment of Organization" ;
    rdfs:comment "Indicates the Organization for which this is a RoleAssignment (inverse of hasRoleAssignment)." ;
    owl:inverseOf :hasRoleAssignment .

:playsRole a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "plays role" ;
    rdfs:comment "Indicates the AgentRole played in a RoleAssignment." .
:playsRole rdf:type owl:FunctionalProperty .
:isRolePlayedInAssignment a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :RoleAssignment ;
    rdfs:label "is role played in Role Assignment" ;
    rdfs:comment "Indicates the RoleAssignment in which this AgentRole is played (inverse of playsRole)." ;
    owl:inverseOf :playsRole .

:inContextOf a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :INVOICMessage ;
    rdfs:label "in context of" ;
    rdfs:comment "Specifies the INVOIC message context for a RoleAssignment." .
:inContextOf rdf:type owl:FunctionalProperty .
:isContextForAssignment a owl:ObjectProperty ;
    rdfs:domain :INVOICMessage ;
    rdfs:range :RoleAssignment ;
    rdfs:label "is context for Role Assignment" ;
    rdfs:comment "Indicates the RoleAssignment for which this INVOICMessage is the context (inverse of inContextOf)." ;
    owl:inverseOf :inContextOf .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an Organization to its Address." .
:isAddressOf a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of Organization" ;
    rdfs:comment "Indicates the Organization to which this Address belongs (inverse of hasAddress)." ;
    owl:inverseOf :hasAddress .

:hasInvoiceAmount a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceAmount ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Links a Summary Section to the Invoice Amount." .
:hasInvoiceAmount rdf:type owl:FunctionalProperty .
:isInvoiceAmountOf a owl:ObjectProperty ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range :SummarySection ;
    rdfs:label "is invoice amount of Summary Section" ;
    rdfs:comment "Indicates the Summary Section for which this is the Invoice Amount (inverse of hasInvoiceAmount)." ;
    owl:inverseOf :hasInvoiceAmount .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links a Summary Section to Tax elements." .
:isTaxOf a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :SummarySection ;
    rdfs:label "is tax of Summary Section" ;
    rdfs:comment "Indicates the Summary Section to which this Tax applies (inverse of hasTax)." ;
    owl:inverseOf :hasTax .

:hasValidationConstraint a owl:ObjectProperty ;
    rdfs:domain :INVOICMessage ;
    rdfs:range :ValidationConstraint ;
    rdfs:label "has validation constraint" ;
    rdfs:comment "Links an INVOIC message to its SHACL or other validation constraints." .
:isValidationConstraintOf a owl:ObjectProperty ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :INVOICMessage ;
    rdfs:label "is validation constraint of INVOIC Message" ;
    rdfs:comment "Indicates the INVOICMessage for which this is a ValidationConstraint (inverse of hasValidationConstraint)." ;
    owl:inverseOf :hasValidationConstraint .

:alignsWithEN16931 a owl:ObjectProperty ;
    rdfs:domain :INVOICMessage ;
    rdfs:range :EN16931Compliance ;
    rdfs:label "aligns with EN 16931" ;
    rdfs:comment "Indicates EN 16931 compliance for an INVOIC message." .
:alignsWithEN16931 rdf:type owl:FunctionalProperty .
:isEN16931ComplianceOf a owl:ObjectProperty ;
    rdfs:domain :EN16931Compliance ;
    rdfs:range :INVOICMessage ;
    rdfs:label "is EN 16931 compliance of INVOIC Message" ;
    rdfs:comment "Indicates the INVOICMessage for which this is the EN16931Compliance (inverse of alignsWithEN16931)." ;
    owl:inverseOf :alignsWithEN16931 .

:alignsWithP2P a owl:ObjectProperty ;
    rdfs:domain :INVOICMessage ;
    rdfs:range :P2POntologyAlignment ;
    rdfs:label "aligns with P2P-O" ;
    rdfs:comment "Indicates P2P-O alignment for an INVOIC message." .
:alignsWithP2P rdf:type owl:FunctionalProperty .
:isP2PAlignmentOf a owl:ObjectProperty ;
    rdfs:domain :P2POntologyAlignment ;
    rdfs:range :INVOICMessage ;
    rdfs:label "is P2P alignment of INVOIC Message" ;
    rdfs:comment "Indicates the INVOICMessage for which this is the P2POntologyAlignment (inverse of alignsWithP2P)." ;
    owl:inverseOf :alignsWithP2P .

:assignedToBusinessProcess a owl:ObjectProperty ;
    rdfs:domain :INVOICMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned to business process" ;
    rdfs:comment "Links an INVOIC message to a business process context." .
:assignedToBusinessProcess rdf:type owl:FunctionalProperty .
:isBusinessProcessOf a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :INVOICMessage ;
    rdfs:label "is business process of INVOIC Message" ;
    rdfs:comment "Indicates the INVOICMessage for which this is the BusinessProcess (inverse of assignedToBusinessProcess)." ;
    owl:inverseOf :assignedToBusinessProcess .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a Segment to its Composite Data Elements." .
:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "is composite element of Segment" ;
    rdfs:comment "Indicates the Segment to which this CompositeDataElement belongs (inverse of hasCompositeElement)." ;
    owl:inverseOf :hasCompositeElement .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a Composite Data Element to its Simple Data Elements." .
:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "is simple element of Composite Data Element" ;
    rdfs:comment "Indicates the CompositeDataElement to which this SimpleDataElement belongs (inverse of hasSimpleElement)." ;
    owl:inverseOf :hasSimpleElement .

#################################################################
# Data Properties
#################################################################

:hasGlobalLocationNumber a owl:DatatypeProperty ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    rdfs:label "has global location number" ;
    rdfs:comment "The Global Location Number (GLN) for an organization." .
:hasGlobalLocationNumber rdf:type owl:FunctionalProperty .

:hasReferenceNumber a owl:DatatypeProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has reference number" ;
    rdfs:comment "The reference number of the invoice document." .
:hasReferenceNumber rdf:type owl:FunctionalProperty .

:hasDocumentDate a owl:DatatypeProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has document date" ;
    rdfs:comment "The date of the invoice document as a string (use ISO 8601)." .
:hasDocumentDate rdf:type owl:FunctionalProperty .

:hasQuantity a owl:DatatypeProperty ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal ;
    rdfs:label "has quantity" ;
    rdfs:comment "The quantity of the item in a line item." .

:elementValue a owl:DatatypeProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range xsd:string ;
    rdfs:label "element value" ;
    rdfs:comment "The value of a simple data element as a string." .
:elementValue rdf:type owl:FunctionalProperty .

#################################################################
# Restrictions and GCAs
#################################################################

:BuyerRole a owl:Class ;
    rdfs:subClassOf :AgentRole ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "The role of buyer in an invoice context." .

:SupplierRole a owl:Class ;
    rdfs:subClassOf :AgentRole ;
    rdfs:label "Supplier Role" ;
    rdfs:comment "The role of supplier in an invoice context." .

:DeliveryPartyRole a owl:Class ;
    rdfs:subClassOf :AgentRole ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "The role of delivery party in an invoice context." .

:RoleAssignmentForBuyer a owl:Class ;
    owl:equivalentClass [ a owl:Restriction ; owl:onProperty :playsRole ; owl:hasValue :BuyerRole ] ;
    rdfs:subClassOf :RoleAssignment ;
    rdfs:label "Role Assignment for Buyer" ;
    rdfs:comment "A RoleAssignment where the AgentRole is Buyer." .

:RoleAssignmentForSupplier a owl:Class ;
    owl:equivalentClass [ a owl:Restriction ; owl:onProperty :playsRole ; owl:hasValue :SupplierRole ] ;
    rdfs:subClassOf :RoleAssignment ;
    rdfs:label "Role Assignment for Supplier" ;
    rdfs:comment "A RoleAssignment where the AgentRole is Supplier." .

:RoleAssignmentForDeliveryParty a owl:Class ;
    owl:equivalentClass [ a owl:Restriction ; owl:onProperty :playsRole ; owl:hasValue :DeliveryPartyRole ] ;
    rdfs:subClassOf :RoleAssignment ;
    rdfs:label "Role Assignment for Delivery Party" ;
    rdfs:comment "A RoleAssignment where the AgentRole is Delivery Party." .

#################################################################
# Additional Connections for Unconnected Classes
#################################################################

:hasReferenceNumberClass a owl:ObjectProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :ReferenceNumber ;
    rdfs:label "has reference number class" ;
    rdfs:comment "Links HeaderSection to ReferenceNumber class for completeness." .
:hasReferenceNumberClass rdf:type owl:FunctionalProperty .
:isReferenceNumberOf a owl:ObjectProperty ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range :HeaderSection ;
    rdfs:label "is reference number of Header Section" ;
    rdfs:comment "Indicates the HeaderSection to which this ReferenceNumber belongs (inverse of hasReferenceNumberClass)." ;
    owl:inverseOf :hasReferenceNumberClass .

:hasGlobalLocationNumberClass a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber ;
    rdfs:label "has global location number class" ;
    rdfs:comment "Links Organization to GlobalLocationNumber class for completeness." .
:hasGlobalLocationNumberClass rdf:type owl:FunctionalProperty .
:isGlobalLocationNumberOf a owl:ObjectProperty ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range :Organization ;
    rdfs:label "is global location number of Organization" ;
    rdfs:comment "Indicates the Organization to which this GlobalLocationNumber belongs (inverse of hasGlobalLocationNumberClass)." ;
    owl:inverseOf :hasGlobalLocationNumberClass .

