@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACT_INVOIC_Story1>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Ontology" ;
    rdfs:comment "A profound ontology for UN/EDIFACT INVOIC messages, segments, and business semantics as described in the provided story." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The top-level envelope containing messages in UN/EDIFACT." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message." .

:INVOICMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "INVOIC Message" ;
    rdfs:comment "An EDIFACT message of type INVOIC for invoices." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." .

:NADSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Header Section" ;
    rdfs:comment "Header section containing document dates and reference numbers." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Detail section listing individual line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Summary section providing totals and tax amounts." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite element." .

:Invoice a owl:Class ;
    rdfs:subClassOf :INVOICMessage ;
    rdfs:label "Invoice" ;
    rdfs:comment "An invoice described by an INVOIC message." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice process." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role (e.g., Buyer, Supplier, Delivery Party) played by an organization in a transaction." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal address for an organization." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A line item sold in the invoice." .

:Price a owl:Class ;
    rdfs:subClassOf :Item ;
    rdfs:label "Price" ;
    rdfs:comment "A price associated with an item." .

:Quantity a owl:Class ;
    rdfs:subClassOf :Item ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity associated with an item." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax component in the invoice." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice may be assigned." .

:EN16931Alignment a owl:Class ;
    rdfs:label "EN 16931 Alignment" ;
    rdfs:comment "Alignment with the European Standard EN 16931-1." .

:P2POAlignment a owl:Class ;
    rdfs:label "P2P-O Alignment" ;
    rdfs:comment "Alignment with the Purchase-to-Pay Ontology (P2P-O)." .

:SHACLConstraint a owl:Class ;
    rdfs:label "SHACL Constraint" ;
    rdfs:comment "A SHACL constraint for validating the knowledge graph." .

:LineItem a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Line Item" ;
    rdfs:comment "A line item in the detail section of the invoice." .

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "A pivot class for assigning a role to an organization in the context of an invoice." .

#################################################################
# Disjointness and DisjointUnion
#################################################################

:BGMSegment owl:disjointWith :NADSegment .
:HeaderSection owl:disjointWith :DetailSection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Address .
:Item owl:disjointWith :Price .

:Segment owl:disjointUnionOf (:BGMSegment :NADSegment :HeaderSection :DetailSection :SummarySection) .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an interchange envelope to the message it contains." ;
    owl:inverseOf :containedInEnvelope .

:containedInEnvelope a owl:ObjectProperty ;
