    rdfs:label "Summary Section" ;
    rdfs:comment "Summary section providing totals and tax amounts." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite element." .

:Invoice a owl:Class ;
    rdfs:subClassOf :INVOICMessage ;
    rdfs:label "Invoice" ;
    rdfs:comment "An invoice described by an INVOIC message." ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasTax ; owl:someValuesFrom :Tax ] ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasItem ; owl:someValuesFrom :Item ] ;
