@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACT_INVOIC_Story1>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Ontology" ;
    rdfs:comment "A profound ontology for UN/EDIFACT INVOIC messages, segments, and business semantics as described in the provided story." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The top-level envelope containing messages in UN/EDIFACT." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message." .

:INVOICMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "INVOIC Message" ;
    rdfs:comment "An EDIFACT message of type INVOIC for invoices." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." .

:NADSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Header Section" ;
    rdfs:comment "Header section containing document dates and reference numbers." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Detail section listing individual line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Summary section providing totals and tax amounts." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite element." .

:Invoice a owl:Class ;
    rdfs:subClassOf :INVOICMessage ;
    rdfs:label "Invoice" ;
    rdfs:comment "An invoice described by an INVOIC message." ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasTax ; owl:someValuesFrom :Tax ] ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasItem ; owl:someValuesFrom :Item ] ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :alignedWithEN16931 ; owl:someValuesFrom :EN16931Alignment ] ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :alignedWithP2PO ; owl:someValuesFrom :P2POAlignment ] ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :assignedBusinessProcess ; owl:someValuesFrom :BusinessProcess ] ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :validatedBySHACL ; owl:someValuesFrom :SHACLConstraint ] .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice process." ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasAddress ; owl:someValuesFrom :Address ] .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role (e.g., Buyer, Supplier, Delivery Party) played by an organization in a transaction." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal address for an organization." ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :addressOfOrganization ; owl:someValuesFrom :Organization ] .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A line item sold in the invoice." ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :itemOfInvoice ; owl:someValuesFrom :Invoice ] .

:Price a owl:Class ;
    rdfs:subClassOf :Item ;
    rdfs:label "Price" ;
    rdfs:comment "A price associated with an item." .

:Quantity a owl:Class ;
    rdfs:subClassOf :Item ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity associated with an item." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax component in the invoice." ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :taxOfInvoice ; owl:someValuesFrom :Invoice ] .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice may be assigned." ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :businessProcessOfInvoice ; owl:someValuesFrom :Invoice ] .

:EN16931Alignment a owl:Class ;
    rdfs:label "EN 16931 Alignment" ;
    rdfs:comment "Alignment with the European Standard EN 16931-1." ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :alignmentOfInvoiceEN16931 ; owl:someValuesFrom :Invoice ] .

:P2POAlignment a owl:Class ;
    rdfs:label "P2P-O Alignment" ;
    rdfs:comment "Alignment with the Purchase-to-Pay Ontology (P2P-O)." ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :alignmentOfInvoiceP2PO ; owl:someValuesFrom :Invoice ] .

:SHACLConstraint a owl:Class ;
    rdfs:label "SHACL Constraint" ;
    rdfs:comment "A SHACL constraint for validating the knowledge graph." ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :validationOfInvoiceSHACL ; owl:someValuesFrom :Invoice ] .

:LineItem a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Line Item" ;
    rdfs:comment "A line item in the detail section of the invoice." .

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "A pivot class for assigning a role to an organization in the context of an invoice." .

#################################################################
# Disjointness and DisjointUnion
#################################################################

:BGMSegment owl:disjointWith :NADSegment .
:HeaderSection owl:disjointWith :DetailSection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Address .
:Item owl:disjointWith :Price .

:Segment owl:disjointUnionOf (:BGMSegment :NADSegment :HeaderSection :DetailSection :SummarySection) .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an interchange envelope to the message it contains." ;
    owl:inverseOf :containedInEnvelope .

:containedInEnvelope a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "contained in envelope" ;
    rdfs:comment "Relates a message to the envelope containing it." ;
    owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a message to its constituent segments." ;
    owl:inverseOf :segmentOfMessage .

:segmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "segment of message" ;
    rdfs:comment "Relates a segment to the message it belongs to." ;
    owl:inverseOf :hasSegment .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Relates a segment to its composite data elements." ;
    owl:inverseOf :compositeElementOfSegment .

:compositeElementOfSegment a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "composite element of segment" ;
    rdfs:comment "Relates a composite data element to the segment it belongs to." ;
    owl:inverseOf :hasCompositeElement .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Relates a composite element to its simple data elements." ;
    owl:inverseOf :simpleElementOfComposite .

:simpleElementOfComposite a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "simple element of composite" ;
    rdfs:comment "Relates a simple data element to the composite data element it belongs to." ;
    owl:inverseOf :hasSimpleElement .

:hasHeader a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :INVOICMessage ;
    rdfs:range :HeaderSection ;
    rdfs:label "has header" ;
    rdfs:comment "Relates an INVOIC message to its header section." ;
    owl:inverseOf :headerOfMessage .

:headerOfMessage a owl:ObjectProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :INVOICMessage ;
    rdfs:label "header of message" ;
    rdfs:comment "Relates a header section to the message it belongs to." ;
    owl:inverseOf :hasHeader .

:hasDetail a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :INVOICMessage ;
    rdfs:range :DetailSection ;
    rdfs:label "has detail" ;
    rdfs:comment "Relates an INVOIC message to its detail section." ;
    owl:inverseOf :detailOfMessage .

:detailOfMessage a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :INVOICMessage ;
    rdfs:label "detail of message" ;
    rdfs:comment "Relates a detail section to the message it belongs to." ;
    owl:inverseOf :hasDetail .

:hasSummary a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :INVOICMessage ;
    rdfs:range :SummarySection ;
    rdfs:label "has summary" ;
    rdfs:comment "Relates an INVOIC message to its summary section." ;
    owl:inverseOf :summaryOfMessage .

:summaryOfMessage a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :INVOICMessage ;
    rdfs:label "summary of message" ;
    rdfs:comment "Relates a summary section to the message it belongs to." ;
    owl:inverseOf :hasSummary .

:hasLineItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "has line item" ;
    rdfs:comment "Relates the detail section to its line items." ;
    owl:inverseOf :lineItemOfDetail .

:lineItemOfDetail a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    rdfs:label "line item of detail" ;
    rdfs:comment "Relates a line item to the detail section it belongs to." ;
    owl:inverseOf :hasLineItem .

:describesInvoice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :INVOICMessage ;
    rdfs:range :Invoice ;
    rdfs:label "describes invoice" ;
    rdfs:comment "Links an INVOIC message to the invoice it describes." ;
    owl:inverseOf :describedByMessage .

:describedByMessage a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :INVOICMessage ;
    rdfs:label "described by message" ;
    rdfs:comment "Links an invoice to the message that describes it." ;
    owl:inverseOf :describesInvoice .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "Relates an invoice to an involved organization." ;
    owl:inverseOf :organizationInvolvedIn .

:organizationInvolvedIn a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Invoice ;
    rdfs:label "organization involved in" ;
    rdfs:comment "Relates an organization to the invoice it is involved in." ;
    owl:inverseOf :involvesOrganization .

:assignedRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "assigned role" ;
    rdfs:comment "Assigns a specific role to an organization in a transaction." ;
    owl:inverseOf :roleAssignmentOfRole .

:roleAssignmentOfRole a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "role assignment of role" ;
    rdfs:comment "Relates an agent role to the role assignments it is part of." ;
    owl:inverseOf :assignedRole .

:assignedOrganization a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "assigned organization" ;
    rdfs:comment "Assigns an organization to a role assignment." ;
    owl:inverseOf :roleAssignmentOfOrganization .

:roleAssignmentOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "role assignment of organization" ;
    rdfs:comment "Relates an organization to the role assignments it is part of." ;
    owl:inverseOf :assignedOrganization .

:assignedInvoice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Invoice ;
    rdfs:label "assigned invoice" ;
    rdfs:comment "Assigns an invoice to a role assignment." ;
    owl:inverseOf :roleAssignmentOfInvoice .

:roleAssignmentOfInvoice a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "role assignment of invoice" ;
    rdfs:comment "Relates an invoice to the role assignments it is part of." ;
    owl:inverseOf :assignedInvoice .

#################################################################
# Data Properties
#################################################################

:hasGlobalLocationNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    rdfs:label "has GLN" ;
    rdfs:comment "Specifies the Global Location Number for an organization." .

:hasRoleIdentifier a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range xsd:string ;
    rdfs:label "role identifier" ;
    rdfs:comment "Identifier for a specific agent role." .

:itemNetPrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range xsd:decimal ;
    rdfs:label "item net price" ;
    rdfs:comment "Net price of an item." .

:itemQuantity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range xsd:decimal ;
    rdfs:label "item quantity" ;
    rdfs:comment "Quantity of an item." .

:invoiceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:decimal ;
    rdfs:label "invoice amount" ;
    rdfs:comment "Total amount of the invoice." .

:invoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string ;
    rdfs:label "invoice number" ;
    rdfs:comment "Unique invoice number." .

:documentDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string ;
    rdfs:label "document date" ;
    rdfs:comment "Date of the invoice document." .

:referenceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string ;
    rdfs:label "reference number" ;
    rdfs:comment "Reference number for the invoice." .

#################################################################
# Pivot Class Reification
#################################################################

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "A pivot class for assigning a role to an organization in the context of an invoice." .

:assignedRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "assigned role" ;
    rdfs:comment "Assigns a specific role to an organization in a transaction." ;
    owl:inverseOf :roleAssignmentOfRole .

:roleAssignmentOfRole a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "role assignment of role" ;
    rdfs:comment "Relates an agent role to the role assignments it is part of." ;
    owl:inverseOf :assignedRole .

:assignedOrganization a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "assigned organization" ;
    rdfs:comment "Assigns an organization to a role assignment." ;
    owl:inverseOf :roleAssignmentOfOrganization .

:roleAssignmentOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "role assignment of organization" ;
    rdfs:comment "Relates an organization to the role assignments it is part of." ;
    owl:inverseOf :assignedOrganization .

:assignedInvoice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Invoice ;
    rdfs:label "assigned invoice" ;
    rdfs:comment "Assigns an invoice to a role assignment." ;
    owl:inverseOf :roleAssignmentOfInvoice .

:roleAssignmentOfInvoice a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "role assignment of invoice" ;
    rdfs:comment "Relates an invoice to the role assignments it is part of." ;
    owl:inverseOf :assignedInvoice .

#################################################################
# Restrictions and Equivalence Axioms
#################################################################
# (Sample for illustration – more can be added as needed)

:BuyerRole a owl:Class ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty :hasRoleIdentifier ;
        owl:hasValue "Buyer"
    ] ;
    rdfs:subClassOf :AgentRole ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "The role of Buyer in a transaction." .

:InvoiceWithTotalAmount a owl:Class ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty :invoiceAmount ;
        owl:someValuesFrom xsd:decimal
    ] ;
    rdfs:subClassOf :Invoice ;
    rdfs:label "Invoice with Total Amount" ;
    rdfs:comment "An invoice that specifies a total amount." .

